      $('#archivedProgramList').innerHTML=archived.map(program=>`<div class="archive-row"><div><strong>${escapeHtml(program.name)}</strong><br><span>${program.length} weeks · ${program.workouts.length} workouts · archived ${escapeHtml(formatLogDate(program.archivedAt))}</span></div><button class="small-button restore-program" type="button" data-program-id="${escapeHtml(program.id)}" ${workoutState.activeProgram?'disabled':''}>Restore</button></div>`).join('');
      document.querySelectorAll('.restore-program').forEach(button=>button.addEventListener('click',()=>{if(workoutState.activeProgram)return;const index=workoutState.archivedPrograms.findIndex(p=>p.id===button.dataset.programId);if(index<0)return;workoutState.activeProgram=workoutState.archivedPrograms.splice(index,1)[0];delete workoutState.activeProgram.archivedAt;renderProgram();renderDashboard();}));
